/**
 * CONCEPT 09: Connected Recycling City
 * Original, asset-free, two-dimensional Canvas animation.
 * Interface: draw(ctx, timeInSeconds, width, height).
 * 25 seconds / 3 scenes / seamless loop / fixed gradient background.
 * Suggested video export: UHD, 60 fps, 100,000,000 bits per second.
 * Bitrate must be applied by the host video encoder, not by Canvas drawing.
 */
'use strict';

const Recycling09 = (() => {
  const TAU = Math.PI * 2;
  const clamp = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v));
  const mix = (a, b, p) => a + (b - a) * p;
  const fract = v => v - Math.floor(v);
  const smooth = v => { const q = clamp(v); return clamp(q * q * q * (q * (q * 6 - 15) + 10)); };
  const wave = v => 0.5 - 0.5 * Math.cos(TAU * v);

  function roundedPath(ctx, x, y, w, h, r = 12) {
    r = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r); ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y); ctx.closePath();
  }
  function rr(ctx, x, y, w, h, r, fill, stroke, lw = 2) {
    roundedPath(ctx, x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function line(ctx, x1, y1, x2, y2, color, lw = 2) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.strokeStyle = color; ctx.lineWidth = lw; ctx.stroke();
  }
  function circle(ctx, x, y, r, fill, stroke, lw = 2) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function poly(ctx, points, fill, stroke, lw = 2) {
    ctx.beginPath(); ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function text(ctx, s, x, y, size, color, maxWidth = 1000, weight = 500, align = 'left') {
    ctx.save(); ctx.textAlign = align; ctx.textBaseline = 'alphabetic';
    ctx.font = weight + ' ' + size + 'px Arial, Helvetica, sans-serif';
    const measured = ctx.measureText(s).width;
    if (measured > maxWidth) {
      size *= maxWidth / measured;
      ctx.font = weight + ' ' + size + 'px Arial, Helvetica, sans-serif';
    }
    ctx.fillStyle = color; ctx.fillText(s, x, y); ctx.restore();
  }
  function arrow(ctx, x, y, a, color, size = 8) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(a);
    poly(ctx, [[size, 0], [-size * 0.65, -size * 0.62], [-size * 0.65, size * 0.62]], color);
    ctx.restore();
  }
  function icon(ctx, kind, x, y, scale, color, ink, surface) {
    ctx.save(); ctx.translate(x, y); ctx.scale(scale, scale);
    if (kind === 0) {
      rr(ctx, -17, -21, 29, 39, 3, surface, ink, 2.2);
      rr(ctx, -11, -17, 28, 39, 3, color, ink, 2.2);
      for (let j = 0; j < 3; j++) line(ctx, -4, -6 + j * 8, 10, -6 + j * 8, ink, 1.6);
    } else if (kind === 1) {
      ctx.beginPath(); ctx.moveTo(-7, -16); ctx.lineTo(-7, -9);
      ctx.bezierCurveTo(-7, -4, -15, -3, -15, 3);
      ctx.lineTo(-15, 21); ctx.quadraticCurveTo(-15, 25, -11, 25);
      ctx.lineTo(11, 25); ctx.quadraticCurveTo(15, 25, 15, 21);
      ctx.lineTo(15, 3); ctx.bezierCurveTo(15, -3, 7, -4, 7, -9);
      ctx.lineTo(7, -16); ctx.closePath(); ctx.fillStyle = color; ctx.fill();
      ctx.strokeStyle = ink; ctx.lineWidth = 2.2; ctx.stroke();
      rr(ctx, -9, -23, 18, 7, 2, surface, ink, 2.2);
      line(ctx, -10, 9, 10, 9, ink, 1.7); line(ctx, -10, 15, 10, 15, ink, 1.7);
    } else if (kind === 2) {
      rr(ctx, -15, -17, 30, 41, 7, color, ink, 2.2);
      rr(ctx, -16, -23, 32, 7, 2, surface, ink, 2.2);
      line(ctx, -8, -8, -8, 14, ink, 1.7); line(ctx, -2, -8, 8, -8, ink, 1.7);
    } else {
      rr(ctx, -16, -21, 32, 44, 6, color, ink, 2.2);
      line(ctx, -12, -13, 12, -13, ink, 1.8); line(ctx, -12, 15, 12, 15, ink, 1.8);
      rr(ctx, -5, -18, 10, 3, 1.5, surface, ink, 1.1);
      line(ctx, -6, -3, 7, -3, ink, 1.7); line(ctx, -6, 3, 7, 3, ink, 1.7);
    }
    ctx.restore();
  }
  function cycleMark(ctx, x, y, r, color, angle = 0, lw = 4) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(angle);
    for (let k = 0; k < 3; k++) {
      const a = k * TAU / 3 - 1.5;
      const end = a + 1.52;
      ctx.beginPath(); ctx.arc(0, 0, r, a, end);
      ctx.strokeStyle = color; ctx.lineWidth = lw; ctx.stroke();
      arrow(ctx, Math.cos(end) * r, Math.sin(end) * r, end + Math.PI / 2, color, lw * 1.65);
    }
    ctx.restore();
  }
  function roller(ctx, x, y, r, angle, fill, ink, accent) {
    circle(ctx, x, y, r, fill, ink, 2.4);
    ctx.save(); ctx.translate(x, y); ctx.rotate(angle);
    for (let i = 0; i < 4; i++) {
      const a = i * Math.PI / 2;
      line(ctx, Math.cos(a) * 9, Math.sin(a) * 9, Math.cos(a) * (r - 9), Math.sin(a) * (r - 9), accent, 3);
    }
    circle(ctx, 0, 0, 5, ink); ctx.restore();
  }
  function flow(ctx, x1, x2, y, phase, color, track, count = 5, size = 7) {
    line(ctx, x1, y, x2, y, track, 2);
    for (let j = 0; j < count; j++) {
      const q = fract(phase + j / count);
      const a = smooth(q / 0.08) * smooth((1 - q) / 0.08);
      ctx.save(); ctx.globalAlpha *= a;
      arrow(ctx, mix(x1 + 10, x2 - 10, q), y, 0, color, size); ctx.restore();
    }
  }
  function title(ctx, n, heading, detail, p) {
    rr(ctx, 52, 30, 42, 34, 9, p.soft, p.border, 1.5);
    text(ctx, '0' + (n + 1), 73, 53, 16, p.ink, 32, 700, 'center');
    text(ctx, heading, 110, 57, 22, p.ink, 1500, 700);
    text(ctx, detail, 52, 94, 16, p.muted, 1600);
  }
  function header(ctx, eyebrow, heading, subtitle, p, label) {
    text(ctx, eyebrow, 112, 79, 14, p.muted, 1100, 700);
    text(ctx, heading, 110, 141, 47, p.ink, 1120, 700);
    text(ctx, subtitle, 112, 180, 19, p.muted, 1120);
    rr(ctx, 1290, 97, 518, 67, 15, p.panel, p.border, 1.8);
    cycleMark(ctx, 1326, 130, 14, p.accent, 0, 2.7);
    text(ctx, label, 1362, 137, 16, p.ink, 420, 600);
  }
  function footer(ctx, timeline, labels, p) {
    line(ctx, 112, 933, 1808, 933, p.border, 1.5);
    for (let i = 0; i < 3; i++) {
      const next = (timeline.currentScene + 1) % 3;
      const weight = (i === timeline.currentScene ? 1 - timeline.transition : 0) + (i === next ? timeline.transition : 0);
      const x = 112 + i * 588;
      rr(ctx, x, 957, 32, 30, 8, p.soft, p.border, 1.2);
      ctx.save(); ctx.globalAlpha = weight;
      rr(ctx, x, 957, 32, 30, 8, p.accent); ctx.restore();
      text(ctx, '0' + (i + 1), x + 16, 978, 13, p.ink, 27, 700, 'center');
      text(ctx, labels[i][0], x + 48, 978, 18, p.ink, 450, 600);
      text(ctx, labels[i][1], x + 48, 1006, 14, p.muted, 450);
      ctx.save(); ctx.globalAlpha = 0.15 + weight * 0.85;
      line(ctx, x + 48, 1021, x + 294, 1021, p.accent, 3); ctx.restore();
    }
  }
  function scenePanel(ctx, timeline, scenes, p) {
    const surface = ctx.createLinearGradient(96, 230, 1824, 900);
    surface.addColorStop(0, p.panel); surface.addColorStop(1, p.panel2);
    rr(ctx, 96, 230, 1728, 670, 25, surface, p.border, 1.8);
    ctx.save(); roundedPath(ctx, 96, 230, 1728, 670, 25); ctx.clip();
    ctx.translate(96, 230);
    const w = 1728, s = timeline.currentScene, q = timeline.transition;
    const pane = (index, offset) => {
      ctx.save(); ctx.translate(offset, 0); ctx.beginPath(); ctx.rect(0, 0, w, 670); ctx.clip();
      scenes[index](ctx, timeline); ctx.restore();
    };
    pane(s, -q * w);
    if (q > 0) pane((s + 1) % 3, (1 - q) * w);
    ctx.restore();
  }

  const P = {
    ink: '#25444F', muted: '#647F87', border: '#AEC6CD', soft: '#E0ECEC',
    panel: '#F8FBF8', panel2: '#EEF5F3', accent: '#6AAEAA', road: '#D6E3E4',
    colors: ['#C7A56B', '#72B8BE', '#90B6A2', '#9BA9CB']
  };
  const names = ['PAPER', 'PLASTIC', 'GLASS', 'METAL'];
  const R = { x: 145, y: 238, w: 837, h: 266, r: 60 };
  const routeLength = r => 2 * (r.w + r.h - 4 * r.r) + TAU * r.r;

  // True circular corners: vehicle tangents agree with the painted road.
  function roadPath(ctx, r) {
    const {x, y, w, h} = r, a = r.r;
    ctx.beginPath(); ctx.moveTo(x + a, y); ctx.lineTo(x + w - a, y);
    ctx.arc(x + w - a, y + a, a, -Math.PI / 2, 0);
    ctx.lineTo(x + w, y + h - a); ctx.arc(x + w - a, y + h - a, a, 0, Math.PI / 2);
    ctx.lineTo(x + a, y + h); ctx.arc(x + a, y + h - a, a, Math.PI / 2, Math.PI);
    ctx.lineTo(x, y + a); ctx.arc(x + a, y + a, a, Math.PI, Math.PI * 1.5); ctx.closePath();
  }
  function routePose(r, phase) {
    const {x, y, w, h} = r, a = r.r;
    const sx = w - 2 * a, sy = h - 2 * a, arc = Math.PI * a / 2;
    let d = fract(phase) * routeLength(r);
    const segments = [
      [sx, q => ({x: x + a + q, y, angle: 0})],
      [arc, q => { const z = -Math.PI / 2 + q / a; return {x: x + w - a + a * Math.cos(z), y: y + a + a * Math.sin(z), angle: z + Math.PI / 2}; }],
      [sy, q => ({x: x + w, y: y + a + q, angle: Math.PI / 2})],
      [arc, q => { const z = q / a; return {x: x + w - a + a * Math.cos(z), y: y + h - a + a * Math.sin(z), angle: z + Math.PI / 2}; }],
      [sx, q => ({x: x + w - a - q, y: y + h, angle: Math.PI})],
      [arc, q => { const z = Math.PI / 2 + q / a; return {x: x + a + a * Math.cos(z), y: y + h - a + a * Math.sin(z), angle: z + Math.PI / 2}; }],
      [sy, q => ({x, y: y + h - a - q, angle: Math.PI * 1.5})],
      [arc, q => { const z = Math.PI + q / a; return {x: x + a + a * Math.cos(z), y: y + a + a * Math.sin(z), angle: z + Math.PI / 2}; }]
    ];
    for (const s of segments) { if (d <= s[0]) return s[1](d); d -= s[0]; }
    return {x: x + a, y, angle: 0};
  }
  function paintedRoad(ctx) {
    roadPath(ctx, R); ctx.lineWidth = 64; ctx.strokeStyle = '#AFC7CD'; ctx.stroke();
    roadPath(ctx, R); ctx.lineWidth = 60; ctx.strokeStyle = P.road; ctx.stroke();
    ctx.save(); ctx.setLineDash([12, 15]); roadPath(ctx, R);
    ctx.lineWidth = 1.7; ctx.strokeStyle = '#A2B9BF'; ctx.stroke(); ctx.restore();
  }
  function building(ctx, x, y, w, h, fill, divisions = 2) {
    rr(ctx, x, y, w, h, 6, fill, P.ink, 1.7);
    line(ctx, x + 9, y + 13, x + w - 9, y + 13, P.ink, 1.4);
    for (let i = 0; i < divisions; i++) {
      const cx = x + (i + 0.5) * w / divisions;
      rr(ctx, cx - 7, y + 28, 14, 18, 2, '#EFF4EC', P.ink, 1.2);
    }
    line(ctx, x + 10, y + h - 11, x + w - 10, y + h - 11, P.ink, 1.3);
  }
  function district(ctx, x, y, label, color) {
    rr(ctx, x, y, 218, 180, 14, '#E7F0EB', '#C5D7D4', 1.2);
    building(ctx, x + 18, y + 18, 82, 83, color, 2);
    building(ctx, x + 116, y + 18, 83, 83, '#D7DDCF', 2);
    rr(ctx, x + 18, y + 116, 181, 27, 4, '#F4F7F1', '#B9CBC9', 1.2);
    for (let i = 0; i < 6; i++) line(ctx, x + 30 + i * 29, y + 123, x + 30 + i * 29, y + 136, '#BBCDCA', 1.3);
    text(ctx, label, x + 109, y + 165, 12, P.muted, 190, 600, 'center');
  }
  function truck(ctx, pose, color, cargo) {
    ctx.save(); ctx.translate(pose.x, pose.y); ctx.rotate(pose.angle);
    for (const x of [-22, 17]) {
      rr(ctx, x - 5, -20, 10, 5, 2, P.ink);
      rr(ctx, x - 5, 15, 10, 5, 2, P.ink);
    }
    rr(ctx, -31, -14, 41, 28, 4, color, P.ink, 2);
    rr(ctx, 11, -13, 19, 26, 4, '#F9FBF5', P.ink, 2);
    rr(ctx, 21, -8, 5, 16, 1.5, '#80ADB6', P.ink, 1.1);
    for (let j = 0; j < 3; j++) line(ctx, -22 + j * 10, -8, -22 + j * 10, 8, P.ink, 1.2);
    rr(ctx, -26, -3, 31, 6, 2, '#F0F4E8');
    rr(ctx, -26, -3, 31 * cargo, 6, 2, '#4A777A');
    ctx.restore();
  }
  function depot(ctx, c) {
    // Opaque transfer housing deliberately occludes vehicles during unloading.
    rr(ctx, 910, 309, 176, 125, 12, '#EDF3E9', P.ink, 2.3);
    rr(ctx, 945, 304, 74, 14, 3, '#B3CDCC', P.ink, 1.7);
    rr(ctx, 945, 425, 74, 14, 3, '#B3CDCC', P.ink, 1.7);
    cycleMark(ctx, 946, 365, 15, '#548A85', 0, 2.8);
    text(ctx, 'RECOVERY', 978, 361, 13, P.ink, 91, 700);
    text(ctx, 'CENTER', 978, 381, 12, P.muted, 91, 600);
    line(ctx, 928, 400, 1068, 400, '#C1D2C9', 1.2);
    for (let i = 0; i < 4; i++) {
      const a = 0.35 + 0.65 * wave(c * 3 - i * 0.125);
      ctx.save(); ctx.globalAlpha = a;
      rr(ctx, 931 + i * 35, 410, 22, 5, 2, P.colors[i]); ctx.restore();
    }
  }
  function station(ctx, x, y, i, c) {
    const a = wave(c * 3 - i * 0.2);
    circle(ctx, x, y, 11, '#F6FAF3', P.ink, 1.8);
    circle(ctx, x, y, 5.5, P.colors[i]);
    ctx.save(); ctx.globalAlpha = 0.3 + a * 0.7;
    line(ctx, x - 7, y + (y < 300 ? -17 : 17), x + 7, y + (y < 300 ? -17 : 17), P.colors[i], 3);
    ctx.restore();
    text(ctx, 'C0' + (i + 1), x + 19, y + 5, 12, P.ink, 60, 700);
  }
  function cityMap(ctx, timeline, withTrucks) {
    const c = timeline.loopT / timeline.duration;
    rr(ctx, 52, 145, 1072, 439, 18, '#F0F6F3', P.border, 1.6);
    text(ctx, withTrucks ? 'COLLECTION ROUTE / TOP VIEW' : 'CONNECTED COLLECTION DISTRICTS', 77, 173, 12, P.muted, 680, 700);
    paintedRoad(ctx);
    district(ctx, 222, 280, 'DISTRICT A', '#C8D9D9');
    district(ctx, 657, 280, 'DISTRICT B', '#DCCFB8');
    // The center block is a separate service compound, clear of the road.
    rr(ctx, 486, 297, 133, 146, 10, '#DBE9E4', '#ACC7C4', 1.5);
    for (let i = 0; i < 3; i++) rr(ctx, 503, 315 + i * 32, 99, 19, 3, '#F5F8EF', '#B9CFCA', 1.2);
    text(ctx, 'SORTED STREAMS', 552.5, 430, 10, P.muted, 114, 700, 'center');
    const coords = [[327, 193], [744, 193], [327, 550], [744, 550]];
    coords.forEach((pos, i) => station(ctx, pos[0], pos[1], i, c));
    if (withTrucks) {
      for (let j = 0; j < 2; j++) {
        const phase = c * 2 + j * 0.5;
        truck(ctx, routePose(R, phase), P.colors[j ? 1 : 0], 0.35 + 0.55 * wave(phase));
      }
    } else {
      for (let j = 0; j < 10; j++) {
        const pose = routePose(R, c * 2 + j / 10);
        arrow(ctx, pose.x, pose.y, pose.angle, '#7AA6AA', 5.5);
      }
    }
    depot(ctx, c);
  }
  function materialRegister(ctx, c) {
    rr(ctx, 1164, 145, 512, 439, 18, '#F8FAF4', P.border, 1.6);
    text(ctx, 'MATERIAL COLLECTION', 1190, 183, 18, P.ink, 458, 700);
    text(ctx, 'Separate streams at every collection point', 1190, 210, 14, P.muted, 458);
    for (let i = 0; i < 4; i++) {
      const y = 257 + i * 77, level = 0.24 + 0.57 * wave(c * 3 - i * 0.2);
      rr(ctx, 1190, y - 25, 48, 51, 9, '#EEF3EA', '#C5D6CD', 1.2);
      icon(ctx, i, 1214, y, 0.7, P.colors[i], P.ink, '#F7FAF2');
      text(ctx, names[i], 1255, y - 2, 15, P.ink, 240, 700);
      text(ctx, 'C0' + (i + 1), 1646, y - 2, 12, P.muted, 55, 600, 'right');
      rr(ctx, 1255, y + 12, 391, 9, 4.5, '#DAE7E2');
      rr(ctx, 1255, y + 12, 391 * level, 9, 4.5, P.colors[i]);
    }
  }
  function logisticsCard(ctx, c) {
    rr(ctx, 1164, 145, 512, 439, 18, '#F8FAF4', P.border, 1.6);
    text(ctx, 'COLLECTION TO RECOVERY', 1190, 183, 18, P.ink, 458, 700);
    text(ctx, 'Controlled routing. Dedicated unloading.', 1190, 210, 14, P.muted, 458);
    const steps = ['COLLECT', 'TRANSPORT', 'TRANSFER', 'RECOVER'];
    line(ctx, 1214, 262, 1214, 499, '#C4D8D2', 2);
    for (let i = 0; i < 4; i++) {
      const cy = 264 + i * 78;
      circle(ctx, 1214, cy, 16, '#EFF5EE', P.ink, 1.6);
      text(ctx, String(i + 1), 1214, cy + 5, 12, P.ink, 25, 700, 'center');
      text(ctx, steps[i], 1250, cy - 5, 15, P.ink, 230, 700);
      text(ctx, ['Separated material bays', 'Continuous collection circuit', 'Enclosed transfer station', 'Four independent material streams'][i], 1250, cy + 17, 13, P.muted, 390);
      const q = 0.34 + 0.53 * wave(c * 2 - i * 0.17);
      rr(ctx, 1549, cy - 12, 94, 7, 3.5, '#DAE7E2');
      rr(ctx, 1549, cy - 12, 94 * q, 7, 3.5, P.accent);
    }
    line(ctx, 1190, 547, 1649, 547, '#D3E0D7', 1.2);
    text(ctx, 'ROUTE MARKERS', 1190, 570, 11, P.muted, 180, 700);
    for (let j = 0; j < 4; j++) rr(ctx, 1469 + j * 45, 558, 31, 7, 3, P.colors[j]);
  }
  function mainHub(ctx, c) {
    rr(ctx, 73, 188, 323, 366, 17, '#E6EFE5', P.ink, 2.2);
    rr(ctx, 96, 211, 277, 37, 7, '#F8FAEF', '#BBCDC0', 1.4);
    text(ctx, 'MATERIAL RECOVERY', 234.5, 235, 16, P.ink, 250, 700, 'center');
    circle(ctx, 234.5, 332, 56, '#F1F6EA', '#A9C7BD', 1.8);
    cycleMark(ctx, 234.5, 332, 32, '#548A82', 0, 5);
    text(ctx, 'SEPARATED RESOURCES', 234.5, 417, 13, P.ink, 264, 700, 'center');
    for (let i = 0; i < 4; i++) {
      const x = 111 + i * 65;
      rr(ctx, x, 446, 49, 53, 6, '#F5F8ED', '#B2C9BC', 1.3);
      icon(ctx, i, x + 24.5, 472, 0.65, P.colors[i], P.ink, '#F7FAEF');
    }
    rr(ctx, 103, 521, 263, 8, 4, '#CCDED1');
    rr(ctx, 103, 521, 263 * (0.4 + 0.44 * wave(c * 3)), 8, 4, P.accent);
  }
  function industry(ctx, i, y) {
    const x = 1277;
    rr(ctx, x, y - 45, 380, 90, 11, '#F4F8F0', P.border, 1.5);
    rr(ctx, x + 20, y - 25, 58, 51, 4, '#DFE9E0', P.ink, 1.6);
    rr(ctx, x + 23, y - 33, 52, 9, 2, P.colors[i], P.ink, 1.4);
    for (let j = 0; j < 3; j++) rr(ctx, x + 28 + j * 15, y - 13, 9, 10, 1, '#F6F8EE', P.ink, 1);
    rr(ctx, x + 42, y + 6, 15, 20, 1.5, '#BACFC3', P.ink, 1.2);
    text(ctx, ['PAPER MILL', 'PLASTICS WORKS', 'GLASS WORKS', 'METAL WORKS'][i], x + 101, y - 3, 16, P.ink, 252, 700);
    text(ctx, ['New sheet stock', 'New material feedstock', 'New containers', 'New formed products'][i], x + 101, y + 21, 13, P.muted, 252);
  }
  function distribution(ctx, timeline) {
    const c = timeline.loopT / timeline.duration;
    title(ctx, 2, 'RETURN TO LOCAL INDUSTRY', 'Recovered resources move through four clear distribution channels.', P);
    mainHub(ctx, c);
    for (let i = 0; i < 4; i++) {
      const y = 233 + i * 102;
      rr(ctx, 420, y - 43, 830, 86, 11, '#F0F5ED', '#C6D8CC', 1.2);
      rr(ctx, 389, y - 10, 31, 20, 4, '#C5DCCE', P.ink, 1.6);
      icon(ctx, i, 454, y, 0.68, P.colors[i], P.ink, '#F7FAF0');
      text(ctx, names[i] + ' STREAM', 490, y - 11, 14, P.ink, 230, 700);
      text(ctx, ['Sorted fibers', 'Sorted polymers', 'Sorted cullet', 'Sorted metals'][i], 490, y + 13, 12, P.muted, 220);
      line(ctx, 732, y, 1277, y, '#C7DAD0', 13);
