function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(width > 0 && height > 0 && Number.isFinite(t)) || t < 0) return;
  const scale = Math.min(minSide / 1080, width / 1920, height / 1080);
  const x = (width - 1920 * scale) * 0.5;
  const y = (height - 1080 * scale) * 0.5;
  const q = Math.max(0, Math.min(1, (sceneProgress - 0.88) / 0.12));
  const transition = Math.max(0, Math.min(1, q * q * q * (q * (q * 6 - 15) + 10)));
  const timeline = { t, duration, sceneCount, loopT, sceneDuration, currentScene, sceneProgress, transition, minSide };
  ctx.save();
  try {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
    ctx.shadowBlur = 0;
    ctx.shadowColor = 'rgba(0,0,0,0)';
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;
    ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.setLineDash([]);
    Recycling10.background(ctx, width, height);
    ctx.translate(x, y); ctx.scale(scale, scale);
    Recycling10.render(ctx, timeline);
  } finally {
    ctx.restore();
  }
}

