  // The drawing surface and its stationary reference marks never move.
  for(let i=0;i<9;i++) circle(ctx,X+44+i*205,Y+H-27,1.4,palette.rule);
  ctx.save(); rr(ctx,X+2,Y+2,W-4,H-4,26); ctx.clip(); ctx.translate(X,Y);
  const s=timeline.transition;
  const indices=s>0?[timeline.currentScene,(timeline.currentScene+1)%3]:[timeline.currentScene];
  indices.forEach((index,j)=>{
    const offset=j===0?-s*W:(1-s)*W;
    ctx.save(); ctx.translate(offset,0);
