// Each route is a rigid translation through a separate transfer corridor.
// Cubic corners use coincident controls at the waypoint: their curvature
// reaches zero at each straight join. Arc-length lookup prevents speed spikes.
function roundedRoute(points,radius=28) {
  const segments=[];
  const lerpPoint=(a,b,u)=>({x:mix(a.x,b.x,u),y:mix(a.y,b.y,u)});
  const point=(segment,u)=>{
    if(segment.kind==='line') return lerpPoint(segment.a,segment.b,u);
    const v=1-u, a=v*v*v, b=3*v*u, d=u*u*u;
    return {x:a*segment.a.x+b*segment.corner.x+d*segment.b.x,
      y:a*segment.a.y+b*segment.corner.y+d*segment.b.y};
  };
  function add(kind,a,b,corner=null) {
    const segment={kind,a,b,corner,length:0,table:[0]};
    const steps=kind==='line'?1:64;
    let previous=a;
    for(let i=1;i<=steps;i++) {
      const next=point(segment,i/steps);
      segment.length+=Math.hypot(next.x-previous.x,next.y-previous.y);
      segment.table.push(segment.length); previous=next;
    }
    if(segment.length>1e-8) segments.push(segment);
  }
  let cursor={x:points[0][0],y:points[0][1]};
  for(let i=1;i<points.length-1;i++) {
    const before={x:points[i-1][0],y:points[i-1][1]};
    const corner={x:points[i][0],y:points[i][1]};
    const after={x:points[i+1][0],y:points[i+1][1]};
    const incoming=Math.hypot(corner.x-before.x,corner.y-before.y);
    const outgoing=Math.hypot(after.x-corner.x,after.y-corner.y);
    const cut=Math.min(radius,incoming*.4,outgoing*.4);
    const entry={x:corner.x-(corner.x-before.x)*cut/incoming,
      y:corner.y-(corner.y-before.y)*cut/incoming};
    const exit={x:corner.x+(after.x-corner.x)*cut/outgoing,
      y:corner.y+(after.y-corner.y)*cut/outgoing};
    add('line',cursor,entry); add('curve',entry,exit,corner); cursor=exit;
  }
  const last=points[points.length-1];
  add('line',cursor,{x:last[0],y:last[1]});
  const length=segments.reduce((sum,segment)=>sum+segment.length,0);
  return {segments,length,point};
}

function routePosition(route,progress) {
  let remaining=ease(progress)*route.length;
  for(let i=0;i<route.segments.length;i++) {
    const segment=route.segments[i];
    if(remaining<=segment.length || i===route.segments.length-1) {
      if(segment.kind==='line') return route.point(segment,clamp(remaining/segment.length));
      const table=segment.table;
      let low=0,high=table.length-1;
      while(high-low>1) {
        const mid=(low+high)>>1;
        if(table[mid]<remaining) low=mid; else high=mid;
      }
      const f=clamp((remaining-table[low])/(table[high]-table[low]));
      return route.point(segment,(low+f)/(table.length-1));
    }
    remaining-=segment.length;
  }
}

