  const length=x2-x1, pitch=36, offset=fract(c*24)*pitch;
  for(let j=-1;j<=Math.ceil(length/pitch);j++) {
    const distance=j*pitch+offset, u=distance/length;
    if(u<0 || u>1) continue;
    const x=left?x2-distance:x1+distance;
    ctx.save(); ctx.globalAlpha*=edge(u,.20);
    line(ctx,x-8,y,x+8,y,color,3.2); ctx.restore();
  }
  arrow(ctx,(x1+x2)/2,y,12,color,left?Math.PI:0);
}

